for (Node* neighbor : current_node->neighbors) {
    // Skip if neighbor has already been visited
    if (!neighbor->visited) {
        // Calculate g value: current node's g + distance to neighbor
        float new_g = current_node->g_value + current_node->distance(*neighbor);

        // Only update if this path is better or neighbor hasn't been processed
        if (new_g < neighbor->g_value || neighbor->g_value == 0.0) {
            neighbor->g_value = new_g;
            neighbor->h_value = neighbor->distance(*end_node);
            neighbor->parent = current_node;

            // Add to open list if not already present
            bool in_open_list = false;
            for (Node* node : open_list) {
                if (node == neighbor) {
                    in_open_list = true;
                    break;
                }
            }
            if (!in_open_list) {
                open_list.push_back(neighbor);
            }
        }
    }
}

